import domain.MenuItem;
import orm.EntityMapper;

import java.util.LinkedHashMap;
import java.util.Map;

public class MenuItemMapper implements EntityMapper<MenuItem> {
    public static final MenuItemMapper INSTANCE = new MenuItemMapper();

    @Override
    public String table() {
        return "menu_item";
    }

    @Override
    public String idOf(MenuItem entity) {
        return entity.id();
    }

    @Override
    public Map<String, Object> toRow(MenuItem e) {
        Map<String, Object> row = new LinkedHashMap<>();
        row.put("category_id", e.categoryId());
        row.put("name", e.name());
        row.put("price_cents", e.priceCents());
        row.put("position", e.position());
        row.put("visible", e.visible());
        return row;
    }

    @Override
    public MenuItem fromRow(Map<String, Object> row) {
        return new MenuItem(
                (String) row.get("id"),
                (String) row.get("category_id"),
                (String) row.get("name"),
                ((Number) row.get("price_cents")).longValue(),
                ((Number) row.get("position")).intValue(),
                Boolean.TRUE.equals(row.get("visible")));
    }
}
package repo;

import domain.Category;
import domain.MenuItem;
import orm.Session;

import java.util.Comparator;
import java.util.List;

public class MenuRepository {
    /** Board order: position, then name so equal positions still list deterministically. */
    public static final Comparator<MenuItem> BOARD_ORDER =
            Comparator.comparingInt(MenuItem::position).thenComparing(MenuItem::name, String.CASE_INSENSITIVE_ORDER);

    public MenuItem item(Session session, String id) {
        return session.find(MenuItemMapper.INSTANCE, id);
    }

    public List<MenuItem> itemsOf(Session session, String categoryId) {
        List<MenuItem> items = session.findWhere(MenuItemMapper.INSTANCE, row -> categoryId.equals(row.get("category_id")));
        items.sort(BOARD_ORDER);
        return items;
    }

    public Category category(Session session, String id) {
        return session.find(CategoryMapper.INSTANCE, id);
    }

    public List<Category> categories(Session session) {
        return session.findWhere(CategoryMapper.INSTANCE, row -> true);
    }

    public void add(Session session, MenuItem item) {
        session.add(MenuItemMapper.INSTANCE, item);
    }

    public void add(Session session, Category category) {
        session.add(CategoryMapper.INSTANCE, category);
    }
}
package service;

import domain.Category;
import domain.MenuItem;
import orm.Transactions;
import repo.MenuRepository;
import util.AuditTrail;

import java.util.List;
import java.util.concurrent.atomic.AtomicLong;

/** Back-office edits of single menu items: create, rename, price, visibility. */
public class MenuEditService {
    public record ItemChange(String name, Long priceCents, Boolean visible) {
        public boolean isEmpty() {
            return name == null && priceCents == null && visible == null;
        }
    }

    private static final int MAX_NAME = 60;

    private final Transactions tx;
    private final MenuRepository repo;
    private final AuditTrail audit;
    private final AtomicLong ids = new AtomicLong();

    public MenuEditService(Transactions tx, MenuRepository repo, AuditTrail audit) {
        this.tx = tx;
        this.repo = repo;
        this.audit = audit;
    }

    public String addItem(String actor, String categoryId, String name, long priceCents) {
        String clean = cleanName(name);
        if (priceCents < 0) {
            throw ApiException.badRequest("price must not be negative");
        }
        return tx.call(s -> {
            Category category = repo.category(s, categoryId);
            if (category == null) {
                throw ApiException.notFound("category " + categoryId);
            }
            List<MenuItem> existing = repo.itemsOf(s, categoryId);
            int position = existing.isEmpty() ? MenuOrderingService.STEP
                    : existing.get(existing.size() - 1).position() + MenuOrderingService.STEP;
            String id = "item-" + ids.incrementAndGet();
            repo.add(s, new MenuItem(id, categoryId, clean, priceCents, position, true));
            s.afterCommit(() -> audit.record(actor, "added " + id + " '" + clean + "'"));
            return id;
        });
    }

    public void change(String actor, String itemId, ItemChange change) {
        if (change.isEmpty()) {
            throw ApiException.badRequest("nothing to change");
        }
        String newName = change.name() == null ? null : cleanName(change.name());
        if (change.priceCents() != null && change.priceCents() < 0) {
            throw ApiException.badRequest("price must not be negative");
        }
        tx.run(s -> {
            MenuItem item = repo.item(s, itemId);
            if (item == null) {
                throw ApiException.notFound("item " + itemId);
            }
            if (newName != null) {
                item.rename(newName);
            }
            if (change.priceCents() != null) {
                item.reprice(change.priceCents());
            }
            if (change.visible() != null) {
                item.setVisible(change.visible());
            }
            s.afterCommit(() -> audit.record(actor, "changed " + itemId + " " + change));
        });
    }

    private static String cleanName(String name) {
        String s = name == null ? "" : name.strip().replaceAll("\\s+", " ");
        if (s.isEmpty() || s.length() > MAX_NAME) {
            throw ApiException.badRequest("name must be 1-" + MAX_NAME + " characters");
        }
        return s;
    }
}
package service;

import domain.MenuItem;
import orm.Transactions;
import repo.MenuRepository;
import util.AuditTrail;

import java.util.List;

/** Drag-and-drop ordering on the menu board. Positions are spaced so single inserts rarely renumber. */
public class MenuOrderingService {
    static final int STEP = 10;

    private final Transactions tx;
    private final MenuRepository repo;
    private final AuditTrail audit;

    public MenuOrderingService(Transactions tx, MenuRepository repo, AuditTrail audit) {
        this.tx = tx;
        this.repo = repo;
        this.audit = audit;
    }

    /** Moves the item so it ends up at {@code index} (0 = top) within its category. */
    public void move(String actor, String itemId, int index) {
        tx.run(s -> {
            MenuItem target = repo.item(s, itemId);
            if (target == null) {
                throw ApiException.notFound("item " + itemId);
            }
            List<MenuItem> items = repo.itemsOf(s, target.categoryId());
            items.remove(target);
            int at = Math.max(0, Math.min(index, items.size()));
            items.add(at, target);
            renumber(items);
            s.afterCommit(() -> audit.record(actor, "moved " + itemId + " to #" + at));
        });
    }

    static void renumber(List<MenuItem> items) {
        int position = STEP;
        for (MenuItem item : items) {
            if (item.position() != position) {
                item.moveTo(position);
            }
            position += STEP;
        }
    }
}

