/**
 * Writes only the columns that differ from what was loaded. Writing whole rows would put back the
 * values this session read earlier and silently undo changes another session committed in between.
 */
void flush() {
    for (Managed m : identityMap.values()) {
        Map<String, Object> current = m.mapper.toRow(m.entity);
        Map<String, Object> changed = new LinkedHashMap<>();
        for (Map.Entry<String, Object> column : current.entrySet()) {
            if (!Objects.equals(m.saved.get(column.getKey()), column.getValue())) {
                changed.put(column.getKey(), column.getValue());
            }
        }
        if (!changed.isEmpty()) {
            db.update(m.mapper.table(), m.mapper.idOf(m.entity), changed);
            m.saved = current;
        }
    }
}

